TLM.f("Commune/C10c",{"officium":"Sancta Maria Sabbato ex Purificatione ad Pascham: Salve Sancta parens","rule":["Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"ruleInherited":["Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C10","sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Concéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:14-16"},{"k":"text","la":"Ab inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 11:27-28"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"text","la":"Felix namque es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8f0eae79d2d2c5a4":{"t":"Sedulije, Ps 44, 2\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove!"},"82c77f3b838d2376":{"t":"<i>Pomolimo se</i>.\nDopusti nama, slugama svojim molimo, Gospodine Bože, da se neprestano radujemo duševnom i tjelesnom zdravlju i da se slavnim zagovorom blažene Marije vazda Djevice oslobodimo sadašnje žalosti i uživamo vječne radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"7ead540ba882eb49":{"t":"Sir 24, 14-16\nČitanje knjige Mudrosti. Bila sam stvorena od početka i prije vjekova i neću prestati do vječnosti. Služila sam pred njim u svetom stanu. I tako sam se utvrdila na Sionu i u svetom sam gradu počinula i u Jeruzalemu je sjedište moje vlasti. Ukorijenila sam se u časnom narodu koji ima udio svoje baštine u mojemu Bogu, a moj je boravak u zboru svetih."},"72576dfa7d6ed562":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu postavši čovjek, onaj koga sav svijet ne može obuhvatiti.\n\nRaduj se, Djevice Marijo, sve si zablude sama uništila. Ti si povjerovala riječima arkanđela Gabrijela. Rodila si Boga i čovjeka ostavši i poslije poroda nepovrijeđena Djevica, Zagovaraj nas, Bogorodice!"},"d34dc2adfd4e4049":{"t":"Lk 11, 27-28\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Kad je Isus govorio narodu, reče mu glasno neka žena iz naroda: Blago tijelu koje te je nosilo i prsima koja su te dojila. On na to odgovori: Još više blago onima koji slušaju Božju riječ i drže je."},"af6c9a47cafda1e9":{"t":"Sretna si, sveta Djevice Marijo, i svake si hvale dostojna, jer je iz tebe isteklo Sunce pravde, Krist Bog naš."},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8587796109dd15d5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>u čašćenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca."},"91ad6f2bf907ac82":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, okrepe našega spasenja, molimo te, da nas svuda štiti zagovor blažene Marije vazda Djevice kojoj smo na čast prinijeli ove žrtve tvojemu veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"ac548dca83598dd4":null}});
